<?php require 'config.php';$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$u=trim($_POST['username']??'');$pw=(string)($_POST['password']??'');if(!preg_match('/^[a-zA-Z0-9_.-]{3,40}$/',$u))$err='Username must be 3–40 characters (letters, numbers, ., _ or -).';elseif(strlen($pw)<10)$err='Password must contain at least 10 characters.';else{try{$p=db();if((int)$p->query('SELECT COUNT(*) FROM users')->fetchColumn()>0)$err='An admin already exists. Delete setup_admin.php and sign in.';else{$s=$p->prepare('INSERT INTO users(username,password_hash) VALUES(?,?)');$s->execute([$u,password_hash($pw,PASSWORD_DEFAULT)]);$msg='Admin created. Delete setup_admin.php from the server, then sign in.';}}catch(Throwable $e){$err='Import database.sql and verify config.php first.';}}} ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set up Nexora Admin</title><link rel="stylesheet" href="assets/style.css"></head><body class="login"><form class="login-card" method="post"><div class="brand"><b>N</b><span>NEXORA<small>SOLUTIONS</small></span></div><h1>Create administrator</h1><p class="muted">Create your first admin account.</p><?php if($err):?><div class="notice error"><?=e($err)?></div><?php endif;?><?php if($msg):?><div class="notice success"><?=e($msg)?></div><a class="btn primary" href="login.php">Go to login →</a><?php else:?><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Username</label><input name="username" minlength="3" required><label>Password (10+ characters)</label><input type="password" name="password" minlength="10" required><button class="btn primary">Create admin →</button><?php endif;?></form></body></html>
